CREATE OR REPLACE PROCEDURE sp (arg1 NUMBER, arg2 VARCHAR2, arg3 NUMBER, arg4 NUMBER)
AS
    total_price NUMBER := 0;
    max_wine_no NUMBER;
    new_price NUMBER;
BEGIN
    -- Process wine entries with score >= threshold
    FOR wine_rec IN (
        SELECT "No", "Grape", "Price", "Winery", "Cases", "Score" 
        FROM "wine"
        WHERE "Score" >= arg1
        FOR UPDATE
    ) LOOP
        -- Add original price to total
        total_price := total_price + wine_rec."Price";

        -- Apply rules in order
        IF INSTR(wine_rec."Grape", 'prefix_') = 1 THEN
            UPDATE "wine" SET "Price" = arg3 
            WHERE CURRENT OF;
        ELSIF wine_rec."No" < arg4 THEN
            DELETE FROM "wine" 
            WHERE CURRENT OF;
        ELSIF wine_rec."Winery" = 'Twomey' THEN
            UPDATE "wine" SET "Price" = arg3 + wine_rec."Price" 
            WHERE CURRENT OF;
        ELSIF wine_rec."Cases" > wine_rec."Score" THEN
            UPDATE "wine" SET "Price" = arg3 + wine_rec."Price" 
            WHERE CURRENT OF;
        ELSE
            UPDATE "wine" SET "Price" = 2 * arg3 
            WHERE CURRENT OF;
        END IF;
    END LOOP;

    -- Find max wine number
    SELECT MAX("No") INTO max_wine_no FROM "wine";
    max_wine_no := COALESCE(max_wine_no, 0) + 1;

    -- Determine new row price
    new_price := CASE WHEN total_price <= arg4 THEN arg3 ELSE arg3 + 1 END;

    -- Insert new row
    INSERT INTO "wine" ("No", "Grape", "Score", "Price")
    VALUES (
        max_wine_no,
        'prefix_' || arg2,
        arg1 + 1,
        new_price
    );
END;

